@classmethod
def from_call(cls, call: "grpc.aio.Call") -> "AioRpcError":
    if not isinstance(call, grpc.aio.Call):
        raise ValueError(f"Expected grpc.aio.Call, got {type(call)}")

    code = call.code()
    if not isinstance(code, grpc.StatusCode):
        raise ValueError(f"Expected grpc.StatusCode, got {type(code)}")

    details = call.details()
    trailing_metadata = call.trailing_metadata()

    try:
        grpc_status_code = code_to_grpc_status_code(code)
    except ValueError as e:
        raise ValueError(f"Unknown grpc status code: {code}") from e

    try:
        status = rpc_status.from_call(call)
    except ValueError as e:
        raise ValueError("Failed to get status from call") from e

    return cls(
        grpc_status_code,
        details=details,
        trailing_metadata=trailing_metadata,
        status=status,
    )
